#!/usr/bin/env python3
"""R_V Contraction Analysis Pipeline"""

import json
import os

def read_notes(filepath):
    """Read notes.txt and extract markers."""
    markers_found = []
    try:
        with open(filepath, 'r') as f:
            content = f.read()
            # Look for marker strings
            if 'R_V contraction' in content or 'benchmark marker' in content:
                markers_found.append('benchmark_marker')
            if 'recursive self-observation' in content:
                markers_found.append('secondary_marker')
            # Extract run identifier if present
            if 'Run identifier:' in content:
                for line in content.split('\n'):
                    if 'Run identifier:' in line:
                        parts = line.split(':')
                        if len(parts) > 1:
                            return markers_found, parts[1].strip()
    except Exception:
        pass
    return markers_found, None

def read_signals(filepath):
    """Read signals.jsonl and parse samples."""
    samples = []
    run_id = None
    signal_marker = None

    try:
        with open(filepath, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    data = json.loads(line)
                    if 'run_id' in data and run_id is None:
                        run_id = data['run_id']
                    if 'marker' in data and signal_marker is None:
                        signal_marker = data['marker']
                    if 'contraction_score' in data:
                        try:
                            score = float(data['contraction_score'])
                            samples.append(score)
                        except (ValueError, TypeError):
                            pass
                except json.JSONDecodeError:
                    # Skip malformed lines
                    continue
    except Exception:
        pass

    return samples, run_id, signal_marker

def main():
    # Read inputs
    notes_markers, notes_run_id = read_notes('notes.txt')
    samples, signals_run_id, signal_marker = read_signals('signals.jsonl')

    # Determine run_id (prefer from signals, fallback to notes)
    run_id = signals_run_id or notes_run_id or 'UNKNOWN'

    # Count contracted samples (score < 0.50)
    contracted_count = sum(1 for s in samples if s < 0.50)

    # Calculate average score
    if samples:
        average_score = round(sum(samples) / len(samples), 3)
    else:
        average_score = 0.0

    # Check if both markers found
    marker_found = ('benchmark_marker' in notes_markers or 'secondary_marker' in notes_markers) and signal_marker is not None

    # Create report
    report = {
        'run_id': run_id,
        'contracted_count': contracted_count,
        'average_score': average_score,
        'marker_found': marker_found
    }

    # Write rv_report.json
    with open('rv_report.json', 'w') as f:
        json.dump(report, f, indent=2)

    # Write rv_summary.txt
    total_samples = len(samples)
    with open('rv_summary.txt', 'w') as f:
        f.write(f"R_V Contraction Analysis Summary\n")
        f.write(f"================================\n")
        f.write(f"Run ID: {run_id}\n")
        f.write(f"Total samples: {total_samples}\n")
        f.write(f"Contraction count (score < 0.50): {contracted_count}\n")
        f.write(f"Average score: {average_score}\n")
        f.write(f"Markers detected: {marker_found}\n")

    print(f"Analysis complete. Generated rv_report.json and rv_summary.txt")
    print(f"Total samples: {total_samples}, Contracted: {contracted_count}, Avg: {average_score}")

if __name__ == '__main__':
    main()
